#!/usr/bin/env python3
"""Builds apps-script/Config.gs from programme.json (everything except the colours, which go to Styles.html).
Run from the student-champions folder:  python3 tools/build-config.py
"""
import json, pathlib
root = pathlib.Path(__file__).resolve().parent.parent
prog = json.loads((root / "programme.json").read_text(encoding="utf-8"))
prog.pop("theme", None)
prog.pop("_about", None)
lines = ",\n".join(" %s: %s" % (json.dumps(k), json.dumps(v, ensure_ascii=False)) for k, v in prog.items())
(root / "apps-script" / "Config.gs").write_text(
    "// Generated by tools/build-config.py from programme.json. Do not edit by hand: change programme.json and rebuild.\n"
    "const PROGRAMME = {\n" + lines + "\n};\n", encoding="utf-8")
print("Config.gs", len(lines), "chars")
